terraform_examples:
module "subnet_mesh" {
  source = "github.com/redwood-inference/infra-modules//modules/subnet-mesh"
  cidr_block = "10.0.0.0/16"
  az_map = {
    "us-east-1a" = "10.0.1.0/24"
    "us-east-1b" = "10.0.2.0/24"
  }
  subnet_roles = ["control", "workload", "infra"]
  egress_mode = "nat_per_az"
  endpoints = ["s3", "sts", "ecr.api"]
  enable_upgrade_hooks = true
}
